/// The guide pages `dartisan mcp:serve` searches, one generated file per
/// page (Blueprint #142, F2): `packages/dartisan_cli/lib/src/guide_pages/`
/// holds `<page>.g.dart`, one `const String` each, written as raw
/// multi-line literals so a line of the page is a line of the file, and
/// `guide_pages.g.dart` is only the index from page name to constant. Two
/// pull requests that change different pages no longer touch the same
/// lines; the map (`guidePages`) is the same, byte for byte.
library;

/// Where the page files go, under the repository root.
const String guidePagesDirectory = 'packages/dartisan_cli/lib/src/guide_pages';

/// Where the index goes.
const String guidePagesIndex =
    'packages/dartisan_cli/lib/src/guide_pages.g.dart';

const String _header =
    '// GENERATED by tool/docs/generate.dart from docs/guide.\n'
    '// Do not edit; run `dart run tool/docs/generate.dart`.\n';

/// The file name of [page] (`id/getting-started.md` →
/// `id_getting_started.g.dart`).
String guidePageFile(String page) =>
    '${page.replaceAll(RegExp(r'\.md$'), '').replaceAll(RegExp('[^A-Za-z0-9]+'), '_').toLowerCase()}.g.dart';

/// The constant of [page] (`id/getting-started.md` → `pageIdGettingStarted`).
String guidePageConstant(String page) {
  final words = page
      .replaceAll(RegExp(r'\.md$'), '')
      .split(RegExp('[^A-Za-z0-9]+'))
      .where((w) => w.isNotEmpty);
  return 'page${[for (final w in words) w[0].toUpperCase() + w.substring(1)].join()}';
}

/// [text] as one Dart string literal: a raw multi-line one, so each line
/// of the text stays a line of the file, `r'''…'''` or, when the text
/// holds `'''` or ends with `'`, `r"""…"""`. Where neither can say it
/// (both quote runs, a first line of only blanks, which Dart drops after
/// the opening quotes, or a control character other than a line feed or a
/// tab: a carriage return, which a multi-line literal reads as a line end,
/// and the others, unreadable in a source file) it is a plain literal on
/// one line, escaped.
///
/// One literal, never adjacent ones: `dart format` lays out a single
/// literal as the generator does, a list of them line by line.
String dartLiteral(String text) {
  if (text.isEmpty) {
    return "''";
  }
  final firstBreak = text.indexOf('\n');
  final rawAllowed =
      !text.runes.any((r) => r < 0x20 && r != 0x0A && r != 0x09) &&
      (firstBreak < 0 ||
          !_droppedFirstLine.hasMatch(text.substring(0, firstBreak)));
  if (rawAllowed) {
    for (final quote in ["'''", '"""']) {
      if (!text.contains(quote) && !text.endsWith(quote[0])) {
        return 'r$quote$text$quote';
      }
    }
  }
  final escaped = StringBuffer();
  for (final rune in text.runes) {
    escaped.write(switch (rune) {
      0x5C => r'\\',
      0x27 => r"\'",
      0x24 => r'\$',
      0x0A => r'\n',
      0x0D => r'\r',
      0x09 => r'\t',
      < 0x20 => '\\u{${rune.toRadixString(16)}}',
      _ => String.fromCharCode(rune),
    });
  }
  return "'$escaped'";
}

/// The file of [page] holding [content].
String renderGuidePage(String page, String content) {
  final declaration = 'const String ${guidePageConstant(page)} =';
  final literal = dartLiteral(content);
  // As `dart format` lays it out: on the same line while the literal's
  // first line fits in 80 columns, else on the next one, indented.
  final firstLine = literal.split('\n').first;
  final value = '$declaration $firstLine'.length <= 80
      ? ' $literal'
      : '\n    $literal';
  return '$_header\n'
      '/// `docs/guide/$page`.\n'
      '$declaration$value;\n';
}

/// The index of [pages] (their names).
String renderGuidePagesIndex(Iterable<String> pages) {
  final sorted = pages.toList()..sort();
  final buffer = StringBuffer(_header)..writeln();
  for (final page in sorted) {
    buffer.writeln("import 'guide_pages/${guidePageFile(page)}';");
  }
  buffer
    ..writeln()
    ..writeln(
      '/// The guide pages (Indonesian ones under `id/`), searched by `mcp:serve`.',
    )
    ..writeln('const Map<String, String> guidePages = {');
  for (final page in sorted) {
    buffer.writeln("  '$page': ${guidePageConstant(page)},");
  }
  buffer.writeln('};');
  return buffer.toString();
}

/// A first line Dart drops after an opening `'''`.
final RegExp _droppedFirstLine = RegExp('^[ \\t\\\\]*\$');

/// Throws a [StateError] naming both pages when two of [pages] would get
/// the same file ([guidePageFile]) or constant ([guidePageConstant]):
/// `a-b.md` and `a_b.md`, `id/mail.md` and `id-mail.md`, names that differ
/// only in case. One would otherwise overwrite the other without a word.
void checkGuidePageNames(Iterable<String> pages) {
  final files = <String, String>{};
  final constants = <String, String>{};
  for (final page in pages.toList()..sort()) {
    final file = guidePageFile(page);
    final constant = guidePageConstant(page).toLowerCase();
    for (final (seen, name, what) in [
      (files, file, 'file $file'),
      (constants, constant, 'constant ${guidePageConstant(page)}'),
    ]) {
      final other = seen[name];
      if (other != null) {
        throw StateError(
          'The guide pages $other and $page would share the $what: rename '
          'one of them.',
        );
      }
      seen[name] = page;
    }
  }
}
